def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 6:
        return 'C'

    opp_d = 0
    my_d = 0
    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1

    trailing_opp_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            trailing_opp_d += 1
        else:
            break

    failed_recovery = 0
    for i in range(2, n):
        if history[i][0] == 'C' and history[i][1] == 'D':
            if history[i - 1][1] == 'D' and history[i - 2][1] == 'D':
                failed_recovery += 1

    recent20_opp_c = 0
    start20 = 0 if n < 20 else n - 20
    for i in range(start20, n):
        if history[i][1] == 'C':
            recent20_opp_c += 1

    if n >= 25 and recent20_opp_c == 0 and failed_recovery >= 1:
        return 'D'

    if trailing_opp_d >= 5 and failed_recovery >= 2:
        return 'D'

    if trailing_opp_d == 1:
        return 'C'
    if trailing_opp_d == 2:
        return 'D'
    if trailing_opp_d >= 3:
        if failed_recovery < 2:
            return 'C'
        return 'D'

    if opp_d == 0:
        if n >= 90 and my_d == 0:
            return 'D'
        if my_d > 0:
            return 'D'

    return 'C'
